// Store a location as GeoJSON
await places.insertOne({
  name: "Taj Mahal",
  location: { type: "Point", coordinates: [78.0421, 27.1751] }
});

// Create 2dsphere index
await places.createIndex({ location: "2dsphere" });

// Find places within 5km
const nearby = await places.find({
  location: {
    $near: {
      $geometry: { type: "Point", coordinates: [78.04, 27.17] },
      $maxDistance: 5000 // metres
    }
  }
}).toArray();
